#' Create a plot from the illuminance prediction data frame
#'
#' * plot_lux() plots the illuminance prediction data frame generated by predict_lux().
#' * •	For more information about MoonShine, including stand-alone scheduler scripts and MoonShineP, see <https://lokpoon.github.io/MoonShine_manual/overview.html>.
#' @param df `data.frame`. Data frame returned by `predict_lux()`.
#' @param illuminance_type_plot `character`. Choose one type of illuminance to plot. See options below. Default is `"total_illuminance_all"`.
#' @param plot_y_max `numeric` or `"AUTO"`. Upper limit of the y-axis. Use `"AUTO"` to let ggplot choose the scale automatically. Default is `0.3`.
#' @param plot_daytime_gray_mask `logical`. If `TRUE`, , shows daytime portions of the plotted line in gray; `FALSE` disables this masking. Default is `TRUE`.
#' @param plot_eclipse_red_mask `logical`. If `TRUE`, adds red shading during lunar eclipses to warn that predicted illuminance may be overestimated because eclipse-related dimming is not modeled; `FALSE` disables the shading. Default is `TRUE`.
#' @param plot_twilight `character`. Select the twilight interval to shade gray: `"astro"` for astronomical twilight (longest), `"nautic"` for nautical twilight (intermediate), `"civil"` for civil twilight (shortest), or `"none"` to disable twilight shading. Default is `"astro"`.
#' @param vertical_time_label `logical`. If `TRUE`, rotate date–time labels vertically.
#' @param time_label_interval_hr `numeric`. Interval between date–time labels, in hours.
#' @param time_label_shift_hr `numeric`. Shift the x-axis start time by the specified number of hours to improve the placement of date–time labels. Negative values move the start time earlier than the first data point, leaving space at the left edge of the plot.
#' @details
#' # `illuminance_type_plot` options:
#' * **"moon_final_lux"** plots only the illuminance of moonlight (plus the darksky_value) during both day and night.
#' * **"moon_final_lux_nighttime"** plots only the illuminance of moonlight at night (no value during daytime, when `sun_altitude` > 0 degrees)
#' * **"moonlight_twilight_nighttime"** plots the illuminance of moonlight plus twilight (no value during daytime, when `sun_altitude` > 0 degrees)
#' * **"twilight"** plots only the illuminance of twilight (defined as the light when `sun_altitude` < 0 degrees).
#' * **"sunlight"** plots only the illuminance of sunlight (defined as the light when `sun_altitude` > 0 degrees).
#' * **"sunlight_twilight"** plots only the sum of sunlight and twilight.
#' * **"total_illuminance_all"** plots all illuminance together, calculated as the sum of moonlight, twilight, and sunlight.
#' * These option names correspond to the column names in the data frame generated by predict_lux().
#' # Notes:
#' * Moonlight and sunlight illuminance differ by several orders of magnitude. Depending on the selected illuminance_type_plot, users may need to adjust plot_y_max or set it to `"AUTO"`.
#' * `plot_daytime_gray_mask` is `TRUE` by default to mask daytime illuminance in gray. This is particularly useful when plotting `"moon_final_lux"` to make it clear that moonlight during daytime should be ignored.
#' * Nighttime is always shaded in dark gray.
#' * Twilight is shaded in light gray. The plot_twilight argument allows users to select astronomical, nautical, or civil twilight, or disable twilight shading.
#' @keywords moonlight
#' @import magrittr
#' @export
#' @return A ggplot object showing predicted ground illuminance through time.
#'   The type of illuminance plotted, corresponding to a specific combination of moonlight, sunlight, and twilight,
#'   depends on the illuminance_type_plot argument in the plot_lux() function
#'   and corresponds to one of the illuminance columns in the data frame produced
#'   by `predict_lux()`.
#' @examples
#' # Plot a data frame generated by predict_lux(), named moonlight_output.
#' # First create a set predictions with predict_lux().
#' moonlight_output <- predict_lux(latitude = -4.21528, longitude = -69.94056, site_elev = 0,
#'                     time_zone = "EST", date_start = "2023-02-27", time_start = "18:00:00",
#'                     duration_day = 10.5, time_interval_minutes = 5, darksky_value = 0.0008,
#'                     output_directory = NULL, export_table = FALSE)
#'
#' # Plot the combined illuminance of moonlight, twilight, and sunlight.
#' plot_lux(df = moonlight_output, illuminance_type_plot = "total_illuminance_all",
#'          plot_y_max = 0.3,  plot_daytime_gray_mask = TRUE, plot_eclipse_red_mask = TRUE,
#'          plot_twilight = "astro", vertical_time_label = TRUE, time_label_interval_hr = 24,
#'          time_label_shift_hr = -5)




plot_lux <- function(df = NULL, illuminance_type_plot = "total_illuminance_all", plot_y_max = 0.3,  plot_daytime_gray_mask = TRUE, plot_eclipse_red_mask = TRUE, plot_twilight = "astro",
                     vertical_time_label = TRUE, time_label_interval_hr = 24, time_label_shift_hr = 0) {

  # Error messages for the arguments

  if (missing(df)) {
    stop("Argument 'df' is missing! See ??MoonShineR::plot_lux")
  }

  #---------------------------PLOTTING

# Create a clean ggplot theme
  theme_rectangular_clean <-
    ggplot2::theme(axis.line = ggplot2::element_line(),
                   panel.grid.major = ggplot2::element_blank(),
                   panel.grid.minor = ggplot2::element_blank(),
                   panel.border = ggplot2::element_blank(),
                   panel.background = ggplot2::element_blank()) +
    ggplot2::theme(axis.text = ggplot2::element_text(size = 12, colour = 'black'),
                   axis.title = ggplot2::element_text(size = 12, colour = 'black')) +
    ggplot2::theme(plot.title = ggplot2::element_text(size = 12)) +
    ggplot2::theme(plot.margin = ggplot2::unit(c(0.25,0.25,0.25,0.25),"cm"))

  # Specify the time of night period and twilight period for shading
  night_time <- dplyr::filter(df, sun_altitude < 0) %>% dplyr::select(datetime)
  night_time <- lubridate::as_datetime(night_time$datetime, tz = lubridate::tz(df$datetime))

  # Extract time interval from df
  time_interval_minutes <- as.double(df$datetime[2] - df$datetime[1], unit = "mins")

  # Define twilight period
  if(plot_twilight == "astro"){twilight_angle <- -18}
  if(plot_twilight == "nautic"){twilight_angle <- -12}
  if(plot_twilight == "civil"){twilight_angle <- -6}
  if(plot_twilight == "none"){twilight_angle <- 0}

  after_twilight_time <- dplyr::filter(df, sun_altitude < (twilight_angle)) %>% dplyr::select(datetime)
  after_twilight_time <- lubridate::as_datetime(after_twilight_time$datetime, tz =  lubridate::tz(df$datetime))

  day_time <- dplyr::filter(df, sun_altitude > 0) %>% dplyr::select(datetime)
  day_time <- lubridate::as_datetime(day_time$datetime, tz = lubridate::tz(df$datetime))

  eclipse_time <- dplyr::filter(df, eclipse == TRUE) %>% dplyr::select(datetime)
  eclipse_time <- lubridate::as_datetime(eclipse_time$datetime, tz = lubridate::tz(df$datetime))

  # Time label interval
  time_label <- paste0(time_label_interval_hr, " hour")

  # shift time label
  shift <- time_label_shift_hr * 60 * 60

  # Mask data frames
  night_mask_df <- data.frame(
    xmin = night_time,
    xmax = night_time + lubridate::dminutes(time_interval_minutes)
  )

  twilight_mask_df <- data.frame(
    xmin = after_twilight_time,
    xmax = after_twilight_time + lubridate::dminutes(time_interval_minutes)
  )

  day_mask_df <- data.frame(
    xmin = day_time,
    xmax = day_time + lubridate::dminutes(time_interval_minutes)
  )

  eclipse_mask_df <- data.frame(
    xmin = eclipse_time,
    xmax = eclipse_time + lubridate::dminutes(time_interval_minutes)
  )

# Plotting:
  if(plot_y_max == "AUTO"){
  plot_output <- ggplot2::ggplot() + theme_rectangular_clean +
    ggplot2::geom_rect(
      data = night_mask_df,
      ggplot2::aes(xmin = xmin, xmax = xmax, ymin = 0, ymax = Inf),
      inherit.aes = FALSE,
      fill = "grey88",
      alpha = 1,
      na.rm = TRUE
    ) +
    ggplot2::geom_rect(
      data = twilight_mask_df,
      ggplot2::aes(xmin = xmin, xmax = xmax, ymin = 0, ymax = Inf),
      inherit.aes = FALSE,
      fill = "grey80",
      alpha = 1,
      na.rm = TRUE
    ) +
    ggplot2::geom_line(data = df, ggplot2::aes(x = datetime, y = .data[[illuminance_type_plot]]), colour = 'black', linewidth = 0.75) +
    ggplot2::scale_x_datetime(date_breaks = time_label,  date_labels = "%Y %b %d %H:%M", limits = c(df$datetime[1] + shift, NA)) + # change the date break here for different x-axis label. A more specific format can be specified.
    ggplot2::scale_y_continuous(
      n.breaks = 4,
      expand = ggplot2::expansion(mult = c(0.05, 0.05))
    ) +
    ggplot2::theme(axis.text.x = ggplot2::element_text(angle = 90, vjust = 0.5, hjust = 1)) + # rotate date label 90 degree.
    ggplot2::labs(x = "", y = "Predicted ground illuminance (lx)") } else {
      plot_output <- ggplot2::ggplot() + theme_rectangular_clean +
        ggplot2::geom_rect(
          data = night_mask_df,
          ggplot2::aes(xmin = xmin, xmax = xmax, ymin = 0, ymax = Inf),
          inherit.aes = FALSE,
          fill = "grey88",
          alpha = 1,
          na.rm = TRUE
        ) +
        ggplot2::geom_rect(
          data = twilight_mask_df,
          ggplot2::aes(xmin = xmin, xmax = xmax, ymin = 0, ymax = Inf),
          inherit.aes = FALSE,
          fill = "grey80",
          alpha = 1,
          na.rm = TRUE
        ) +
        ggplot2::geom_line(data = df, ggplot2::aes(x = datetime, y = .data[[illuminance_type_plot]]), colour = 'black', linewidth = 0.75) +
        ggplot2::scale_y_continuous(
          n.breaks = 4,
          expand = ggplot2::expansion(mult = c(0.05, 0.05))
        ) +
        ggplot2::coord_cartesian(ylim = c(0, plot_y_max)) +
        ggplot2::scale_x_datetime(date_breaks = time_label, date_labels = "%Y %b %d %H:%M", limits = c(df$datetime[1] + shift, NA)) + # change the date break here for different x-axis label. A more specific format can be specified.
        ggplot2::labs(x = "", y = "Predicted ground illuminance (lx)") }

  # Daytime mask
  if(plot_daytime_gray_mask == TRUE){
    plot_output <- plot_output +
      ggplot2::geom_rect(
        data = day_mask_df,
        ggplot2::aes(
          xmin = xmin,
          xmax = xmax,
          ymin = 0,
          ymax = Inf
        ),
        inherit.aes = FALSE,
        fill = "white",
        alpha = 0.85,
        na.rm = TRUE
      )
  }

  # Eclipse mask
  if(plot_eclipse_red_mask == TRUE){
    plot_output <- plot_output +
      ggplot2::geom_rect(
        data = eclipse_mask_df,
        ggplot2::aes(
          xmin = xmin,
          xmax = xmax,
          ymin = 0,
          ymax = Inf
        ),
        inherit.aes = FALSE,
        fill = "red",
        alpha = 0.5,
        na.rm = TRUE
      )
  }

  # Vertical time label
  if(vertical_time_label == TRUE){
    plot_output <- plot_output +
      ggplot2::theme(axis.text.x = ggplot2::element_text(angle = 90, vjust = 0.5, hjust = 1))} # rotate date label 90 degree.


  plot_output
}


  #---------------------------END OF SCRIPT---------------------------
